<script lang="ts">
  // Third-party notices, generated by scripts/gen-licenses.mjs into
  // public/licenses.json. Searchable list; a row expands to its licence text.
  import { onMount, tick } from 'svelte'
  import { errorMessage, openExternal } from '$lib/api/commands'
  import { pushHandler } from '$lib/gamepad/input.svelte'
  import { t } from '$lib/i18n/index.svelte'
  import { notify } from '$lib/state/toast.svelte'

  interface Pkg {
    kind: 'origin' | 'bundled' | 'asset' | 'rust' | 'js'
    name: string
    version: string
    license: string
    repository: string
    note?: string
    texts: string[]
  }
  interface Data {
    generated: string
    packages: Pkg[]
    texts: Record<string, string>
  }
  interface Props {
    onclose: () => void
  }
  let { onclose }: Props = $props()

  let data = $state<Data | null>(null)
  let error = $state<string | null>(null)
  let query = $state('')
  let openKey = $state<string | null>(null)
  let closeBtn = $state<HTMLButtonElement | undefined>()

  const GROUPS: Array<{ kind: Pkg['kind']; label: () => string }> = [
    { kind: 'origin', label: () => t('licenses.origin', 'Based on') },
    { kind: 'bundled', label: () => t('licenses.bundled', 'Bundled programs') },
    { kind: 'asset', label: () => t('licenses.assets', 'Icons and artwork') },
    { kind: 'rust', label: () => t('licenses.rust', 'Rust libraries') },
    { kind: 'js', label: () => t('licenses.js', 'JavaScript libraries') }
  ]

  const filtered = $derived.by(() => {
    const q = query.trim().toLowerCase()
    const list = data?.packages ?? []
    return q ? list.filter((p) => p.name.toLowerCase().includes(q) || p.license.toLowerCase().includes(q)) : list
  })
  const summary = $derived.by(() => {
    const counts = new Map<string, number>()
    for (const p of data?.packages ?? []) counts.set(p.license, (counts.get(p.license) ?? 0) + 1)
    return [...counts.entries()].sort((a, b) => b[1] - a[1]).slice(0, 6)
  })

  onMount(() => {
    fetch('/licenses.json')
      .then((r) => (r.ok ? r.json() : Promise.reject(new Error(`HTTP ${r.status}`))))
      .then((d: Data) => (data = d))
      .catch((e) => (error = String(e)))
    tick().then(() => closeBtn?.focus())
    const off = pushHandler((a) => {
      if (a === 'back') {
        onclose()
        return true
      }
      return false
    })
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        e.stopPropagation()
        onclose()
      }
    }
    window.addEventListener('keydown', onKey, true)
    return () => {
      off()
      window.removeEventListener('keydown', onKey, true)
    }
  })

  const key = (p: Pkg) => `${p.kind}:${p.name}@${p.version}`
</script>

<div class="backdrop" role="presentation" onclick={(e) => e.target === e.currentTarget && onclose()}>
  <div class="dialog" role="dialog" aria-modal="true" aria-labelledby="lic-title" data-focus-scope>
    <header>
      <div>
        <h2 id="lic-title">{t('licenses.title', 'Open-source licences')}</h2>
        <p class="muted small">
          {t('licenses.intro', 'Hyper is free software under GPL-3.0 and is built on the work of these projects.')}
          {#if data}· {data.packages.length} {t('licenses.components', 'components')}{/if}
        </p>
      </div>
      <button class="btn" bind:this={closeBtn} onclick={onclose}>{t('licenses.close', 'Close')}</button>
    </header>

    {#if data}
      <div class="tools">
        <input type="search" placeholder={t('licenses.search', 'Search by name or licence')} bind:value={query} />
        <div class="chips">
          {#each summary as [lic, n] (lic)}
            <button class="chip" class:on={query === lic} onclick={() => (query = query === lic ? '' : lic)}>{lic} · {n}</button>
          {/each}
        </div>
      </div>
      <div class="list">
        {#each GROUPS as g (g.kind)}
          {@const items = filtered.filter((p) => p.kind === g.kind)}
          {#if items.length}
            <h3>{g.label()} <span class="muted">({items.length})</span></h3>
            {#each items as p (key(p))}
              {@const k = key(p)}
              <div class="item" class:open={openKey === k}>
                <button class="row" aria-expanded={openKey === k} onclick={() => (openKey = openKey === k ? null : k)}>
                  <span class="name">{p.name}{#if p.version}<span class="ver">{p.version}</span>{/if}</span>
                  <span class="lic" title={p.license}>{p.license}</span>
                </button>
                {#if openKey === k}
                  <div class="body">
                    {#if p.note}<p class="note">{p.note}</p>{/if}
                    <button class="link" onclick={() => openExternal(p.repository).catch((e) => notify(errorMessage(e), 'error'))}>{p.repository}</button>
                    {#each p.texts as id (id)}
                      <pre>{data.texts[id]}</pre>
                    {/each}
                  </div>
                {/if}
              </div>
            {/each}
          {/if}
        {/each}
      </div>
    {:else if error}
      <p class="muted">{error}</p>
    {:else}
      <p class="muted">…</p>
    {/if}
  </div>
</div>

