    font-size: 13px;
  }
  .link {
    padding: 0;
    font-size: 13px;
    color: var(--accent-overlay);
    text-decoration: underline;
    word-break: break-all;
    text-align: left;
  }
  pre {
    margin: 10px 0 0;
    max-height: 320px;
    overflow: auto;
    padding: 10px;
    border-radius: 6px;
    background: var(--body-background);
    font-size: 12px;
    line-height: 1.45;
    white-space: pre-wrap;
    user-select: text;
  }
</style>
